-- boom-364.3: labels catalog moved from TypeScript to the DB. Previously the
-- 114-entry manifest lived in web/shared/features/publicprofile/labels/catalog.ts
-- and every edit required a PR + deploy — painful for iterating on prompts +
-- imagery. Post-pivot, the FE fetches /api/v1/labels/catalog and the admin
-- CRUD tab edits rows live.
--
-- Schema:
--   id                — stable slug (e.g. "python-master", "late-night-coder").
--                       Same values the TS catalog used, so persisted user
--                       awards + label_images rows stay linked.
--   kind              — tier | archetype | tribe | meme (mirrors LabelSpec.kind).
--   label             — SHOUTY UPPERCASE display string.
--   glyph             — optional 1-3 char icon (emoji or symbol).
--   description       — rich narrative (2-3 sentences). Human-facing.
--                       Populated from the creative-writer manifest (boom-364.2).
--   optimized_prompt  — SDXL/Chroma tag-heavy string sent to comfyui at gen
--                       time. Concatenated as `${systemPrompt}, ${optimizedPrompt}`.
--   rank              — display priority; higher shows first in the hero top-N.
--                       Preserved 1:1 from the TS catalog so the same top-3
--                       lands on live profiles pre/post pivot.
--   tier              — for kind='tier', which tier band (novice..legend).
--                       Drives the "keep highest tier per axis-value" dedupe
--                       in the FE evaluator.
--   condition         — JSONB discriminated-union predicate tree. Round-trips
--                       through the DB unchanged (jsonb preserves nested
--                       structure). Evaluator reads the same shape it did
--                       when it lived in TypeScript.
--
-- The (kind, rank DESC) index is what the FE evaluator wants: fetch-and-sort
-- happens once per public-profile render, filter by kind for grouping.
--
-- Additive-safe: an old pod running the pre-pivot image on the same DB simply
-- ignores this table. No column-drop, no rename, no destructive ALTER.

CREATE TABLE public.labels (
    id                TEXT PRIMARY KEY,
    kind              TEXT NOT NULL CHECK (kind IN ('tier', 'archetype', 'tribe', 'meme')),
    label             TEXT NOT NULL,
    glyph             TEXT,
    description       TEXT,
    optimized_prompt  TEXT,
    rank              INTEGER NOT NULL DEFAULT 0,
    tier              TEXT,
    condition         JSONB NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX labels_kind_rank ON public.labels(kind, rank DESC);

-- Singleton config row for the global generation systemPrompt. One-row-table
-- pattern (singleton BOOLEAN PRIMARY KEY DEFAULT true CHECK (= true)) so
-- UPDATE ... WHERE singleton = true is always the write path — INSERT
-- attempts fail the CHECK+PK combo and can't accidentally spawn a second
-- config row.
CREATE TABLE public.label_gen_config (
    singleton     BOOLEAN PRIMARY KEY DEFAULT true CHECK (singleton = true),
    system_prompt TEXT NOT NULL DEFAULT '',
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Seed: 114 label rows. Derived byte-for-byte from
-- web/shared/features/publicprofile/labels/catalog.ts (id, kind, label, glyph,
-- rank, tier, condition) + the creative-writer manifest (boom-364.2) at
-- web/shared/features/publicprofile/labels/prompts.manifest.json (description,
-- optimizedPrompt, systemPrompt).
--
-- Generator: scripts/gen_labels_seed.mts (committed so the derivation is
-- reviewable). Regeneration is idempotent — same TS + manifest input yields
-- byte-identical SQL output. Once merged, this migration is frozen; new
-- labels come in via the admin CRUD UI or a fresh migration.


-- label_gen_config singleton — global systemPrompt.
UPDATE label_gen_config SET system_prompt = 'cyberpunk anime chibi half-body emblem portrait, Arasaka corporate aesthetic, deep crimson red rim light on jet black background, centered subject, muted red highlights, clean linework, high detail sharp cel shading, 8k illustration, no text no watermark no signature no logo', updated_at = now() WHERE singleton = true;

-- +goose StatementEnd

-- +goose Down
-- +goose StatementBegin
DROP TABLE IF EXISTS public.labels;
DROP TABLE IF EXISTS public.label_gen_config;
-- +goose StatementEnd
